import argparse
import json
import os
import pickle

import numpy as np
import pandas as pd
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.model_selection import StratifiedKFold

try:
    import lightgbm as lgb
    HAS_LGB = True
except Exception:
    HAS_LGB = False


TE_KEYS = [
    ["coupon"],
    ["occupation"],
    ["maritalStatus", "has_children"],
    ["coupon", "has_children"],
    ["time", "coupon"],
    ["income", "coupon"],
]


class Preprocessor(object):
    def __init__(self):
        self.features = []
        self.num_cols = []
        self.cat_cols = []
        self.medians = {}
        self.cat_maps = {}

    def fit(self, df, feature_columns):
        self.features = list(feature_columns)
        self.num_cols = []
        self.cat_cols = []
        self.medians = {}
        self.cat_maps = {}
        for c in self.features:
            if c not in df.columns:
                self.cat_cols.append(c)
                self.cat_maps[c] = {"__NA__": 0}
                continue
            s = df[c]
            num = pd.to_numeric(s, errors="coerce")
            frac = float(num.notna().mean()) if len(s) > 0 else 0.0
            nun = int(num.nunique(dropna=True))
            if frac >= 0.9 and nun > 10:
                self.num_cols.append(c)
                med = float(np.nanmedian(num.values)) if num.notna().any() else 0.0
                self.medians[c] = med
            else:
                self.cat_cols.append(c)
                s2 = s.astype(object).where(s.notna(), "__NA__").astype(str)
                vals = pd.unique(s2.values)
                mapping = {v: i for i, v in enumerate(sorted(vals))}
                self.cat_maps[c] = mapping
        return self

    def transform(self, df):
        n = len(df)
        out = np.zeros((n, len(self.features)), dtype=np.float64)
        for j, c in enumerate(self.features):
            if c in self.medians:
                if c in df.columns:
                    num = pd.to_numeric(df[c], errors="coerce").values.astype(np.float64)
                else:
                    num = np.full(n, np.nan, dtype=np.float64)
                num = np.where(np.isnan(num), self.medians[c], num)
                out[:, j] = num
            else:
                mp = self.cat_maps.get(c, {"__NA__": 0})
                if c in df.columns:
                    vals = df[c].astype(object).where(df[c].notna(), "__NA__").astype(str).values
                else:
                    vals = np.array(["__NA__"] * n, dtype=object)
                out[:, j] = np.array([mp.get(v, -1) for v in vals], dtype=np.float64)
        return out


def build_matrix(X, feats, cat_idx):
    arr = np.array(X, dtype=np.float64, copy=True)
    if cat_idx:
        for j in cat_idx:
            col = arr[:, j]
            col = np.where(np.isnan(col), -1.0, col)
            arr[:, j] = np.round(col)
    return arr


class TargetEncoder(object):
    def __init__(self, keys, smoothing=10.0, n_splits=5, seed=42):
        self.keys = [list(k) for k in keys]
        self.smoothing = float(smoothing)
        self.n_splits = int(n_splits)
        self.seed = int(seed)
        self.maps = []
        self.prior = 0.0

    @staticmethod
    def _key_series(df, cols):
        keys = None
        for c in cols:
            if c in df.columns:
                s = df[c].astype(object).where(df[c].notna(), "__NA__").astype(str).values
            else:
                s = np.array(["__NA__"] * len(df), dtype=object)
            if keys is None:
                keys = np.array(s, dtype=object)
            else:
                keys = np.array([a + "|" + b for a, b in zip(keys, s)], dtype=object)
        return keys

    def _map_from(self, keys, y, prior):
        agg = pd.DataFrame({"k": np.asarray(keys), "y": np.asarray(y, dtype=np.float64)})
        agg = agg.groupby("k")["y"].agg(["mean", "count"])
        m = (agg["mean"] * agg["count"] + prior * self.smoothing) / (agg["count"] + self.smoothing)
        return m.to_dict()

    def fit(self, df, y):
        y = np.asarray(y, dtype=np.float64)
        self.prior = float(np.mean(y)) if len(y) else 0.0
        self.maps = []
        for cols in self.keys:
            ks = self._key_series(df, cols)
            self.maps.append(self._map_from(ks, y, self.prior))
        return self

    def transform(self, df):
        if not self.keys:
            return np.zeros((len(df), 0), dtype=np.float64)
        outs = []
        for i, cols in enumerate(self.keys):
            ks = self._key_series(df, cols)
            m = self.maps[i]
            prior = self.prior
            outs.append(np.array([m.get(k, prior) for k in ks], dtype=np.float64))
        return np.stack(outs, axis=1)

    def fit_transform_oof(self, df, y):
        y = np.asarray(y, dtype=np.float64)
        n = len(y)
        n_feat = len(self.keys)
        out = np.zeros((n, n_feat), dtype=np.float64)
        if n_feat == 0 or n == 0:
            self.fit(df, y)
            return out
        _, counts = np.unique(y, return_counts=True)
        min_count = int(counts.min()) if len(counts) else n
        if min_count < 2:
            self.fit(df, y)
            out[:] = float(np.mean(y))
            return out
        n_splits = min(self.n_splits, max(2, min_count))
        skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=self.seed)
        key_cache = [self._key_series(df, cols) for cols in self.keys]
        for tr, va in skf.split(np.zeros(n), y):
            prior_k = float(np.mean(y[tr]))
            for i in range(n_feat):
                ks = key_cache[i]
                m = self._map_from(ks[tr], y[tr], prior_k)
                out[va, i] = np.array([m.get(k, prior_k) for k in ks[va]], dtype=np.float64)
        self.fit(df, y)
        return out


def _make_lgb(n_cls, seed):
    params = dict(
        n_estimators=600,
        learning_rate=0.03,
        num_leaves=31,
        min_child_samples=20,
        subsample=0.9,
        subsample_freq=1,
        colsample_bytree=0.9,
        reg_lambda=1.0,
        random_state=seed,
        n_jobs=2,
        verbose=-1,
    )
    if n_cls == 2:
        params["objective"] = "binary"
    else:
        params["objective"] = "multiclass"
        params["num_class"] = n_cls
    return lgb.LGBMClassifier(**params)


def _make_hgb(seed):
    return HistGradientBoostingClassifier(
        max_iter=400,
        learning_rate=0.05,
        max_leaf_nodes=31,
        min_samples_leaf=20,
        l2_regularization=1.0,
        random_state=seed,
    )


def fit_predict_fold(arr, y, tr, va, n_cls, cat_idx, seed=42):
    Xtr = arr[tr]
    ytr = y[tr]
    Xva = arr[va]
    n = len(va)
    pl = np.zeros((n, n_cls), dtype=np.float64)
    ph = np.zeros((n, n_cls), dtype=np.float64)

    if HAS_LGB:
        try:
            m = _make_lgb(n_cls, seed)
            kw = {}
            if cat_idx:
                kw["categorical_feature"] = list(cat_idx)
            m.fit(Xtr, ytr, **kw)
            p = m.predict_proba(Xva)
            for i, cl in enumerate(m.classes_):
                pl[:, int(cl)] = p[:, i]
        except Exception as e:
            print("[train] lgb fold failed: %s" % e)
            pl = None
    else:
        pl = None

    try:
        h = _make_hgb(seed)
        h.fit(Xtr, ytr)
        p = h.predict_proba(Xva)
        for i, cl in enumerate(h.classes_):
            ph[:, int(cl)] = p[:, i]
    except Exception as e:
        print("[train] hgb fold failed: %s" % e)
        ph = None

    if pl is None and ph is None:
        pl = np.full((n, n_cls), 1.0 / n_cls)
        ph = pl.copy()
    elif pl is None:
        pl = ph.copy()
    elif ph is None:
        ph = pl.copy()
    return pl, ph


def train_full(arr, y, n_cls, cat_idx):
    lgbs = []
    hgbs = []
    for seed in [42, 55, 68, 81, 94]:
        if HAS_LGB:
            try:
                m = _make_lgb(n_cls, seed)
                kw = {}
                if cat_idx:
                    kw["categorical_feature"] = list(cat_idx)
                m.fit(arr, y, **kw)
                lgbs.append(m)
            except Exception as e:
                print("[train] lgb final failed: %s" % e)
        try:
            h = _make_hgb(seed)
            h.fit(arr, y)
            hgbs.append(h)
        except Exception as e:
            print("[train] hgb final failed: %s" % e)
    return lgbs, hgbs


def cmd_train(args):
    data = args.data
    model_dir = args.model
    os.makedirs(model_dir, exist_ok=True)

    with open(os.path.join(data, "schema.json")) as f:
        schema = json.load(f)
    feature_columns = schema.get("feature_columns")

    df = pd.read_csv(os.path.join(data, "features.csv"))
    lab = pd.read_csv(os.path.join(data, "labels.csv"))
    if feature_columns is None:
        feature_columns = [c for c in df.columns]
    feature_columns = [c for c in feature_columns if c in df.columns]

    n = min(len(df), len(lab))
    df = df.iloc[:n].reset_index(drop=True)
    y_raw = lab["label"].values[:n]

    uniq = sorted(list(pd.unique(y_raw)), key=lambda v: str(v))
    lab_map = {v: i for i, v in enumerate(uniq)}
    y = np.array([lab_map[v] for v in y_raw], dtype=np.int64)
    n_cls = len(uniq)

    pre = Preprocessor()
    pre.fit(df, feature_columns)
    X = pre.transform(df)
    base_feats = list(pre.features)
    cat_idx = [base_feats.index(c) for c in pre.cat_cols if c in base_feats]
    arr = build_matrix(X, base_feats, cat_idx)

    te = None
    n_te = 0
    if n_cls == 2:
        te_keys = [list(k) for k in TE_KEYS if all(c in df.columns for c in k)]
        if te_keys:
            try:
                te = TargetEncoder(te_keys, smoothing=10.0, n_splits=5, seed=42)
                te_oof = te.fit_transform_oof(df, y)
                if te_oof.shape[1] > 0:
                    arr = np.concatenate([arr, te_oof], axis=1)
                    n_te = int(te_oof.shape[1])
            except Exception as e:
                print("[train] te failed: %s" % e)
                te = None
                n_te = 0
    feats = base_feats + ["__te_%d" % i for i in range(n_te)]

    print("[train] rows=%d base=%d cat=%d te=%d classes=%d" % (n, len(base_feats), len(cat_idx), n_te, n_cls))

    oof_l = np.zeros((n, n_cls), dtype=np.float64)
    oof_h = np.zeros((n, n_cls), dtype=np.float64)
    if n_cls > 0:
        min_count = int(np.bincount(y, minlength=n_cls).min())
    else:
        min_count = 0
    n_splits = int(min(5, max(2, min_count))) if min_count >= 2 else 0
    if n_splits >= 2:
        skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=42)
        for fold, (tr, va) in enumerate(skf.split(arr, y)):
            pl, ph = fit_predict_fold(arr, y, tr, va, n_cls, cat_idx, seed=42)
            oof_l[va] = pl
            oof_h[va] = ph
    else:
        oof_l[:] = 1.0 / max(n_cls, 1)
        oof_h[:] = 1.0 / max(n_cls, 1)

    best = {"acc": -1.0, "w": 0.5, "thr": 0.5}
    if n > 0:
        for w in np.arange(0.0, 1.0001, 0.1):
            p = float(w) * oof_l + (1.0 - float(w)) * oof_h
            if n_cls == 2:
                for thr in np.arange(0.30, 0.7001, 0.01):
                    pred = (p[:, 1] >= thr).astype(np.int64)
                    acc = float((pred == y).mean())
                    if acc > best["acc"]:
                        best = {"acc": acc, "w": float(w), "thr": float(thr)}
            else:
                pred = p.argmax(axis=1)
                acc = float((pred == y).mean())
                if acc > best["acc"]:
                    best = {"acc": acc, "w": float(w), "thr": 0.5}
    print("[train] oof acc=%.4f blend_w=%.2f thr=%.2f" % (best["acc"], best["w"], best["thr"]))

    lgbs, hgbs = train_full(arr, y, n_cls, cat_idx)

    with open(os.path.join(model_dir, "preprocessor.pkl"), "wb") as f:
        pickle.dump(pre, f)
    if te is not None and n_te > 0:
        with open(os.path.join(model_dir, "te.pkl"), "wb") as f:
            pickle.dump(te, f)
    with open(os.path.join(model_dir, "models.pkl"), "wb") as f:
        pickle.dump({"lgbs": lgbs, "hgbs": hgbs}, f)

    bundle = {
        "features": list(feats),
        "base_features": list(base_feats),
        "cat_idx": list(cat_idx),
        "n_te": int(n_te),
        "blend_w": float(best["w"]),
        "threshold": float(best["thr"]),
        "classes": [c.item() if hasattr(c, "item") else c for c in uniq],
        "n_cls": int(n_cls),
        "oof_accuracy": float(best["acc"]),
        "has_lgb": bool(len(lgbs) > 0),
        "has_hgb": bool(len(hgbs) > 0),
    }
    with open(os.path.join(model_dir, "config.json"), "w") as f:
        json.dump(bundle, f)
    print("[train] saved model to %s (%d lgb, %d hgb)" % (model_dir, len(lgbs), len(hgbs)))


def _avg_proba(models, arr, n_cls):
    if not models:
        return None
    acc = np.zeros((arr.shape[0], n_cls), dtype=np.float64)
    cnt = 0
    for m in models:
        try:
            p = m.predict_proba(arr)
            out = np.zeros((arr.shape[0], n_cls), dtype=np.float64)
            for i, cl in enumerate(m.classes_):
                out[:, int(cl)] = p[:, i]
            acc += out
            cnt += 1
        except Exception as e:
            print("[predict] model failed: %s" % e)
    if cnt == 0:
        return None
    return acc / float(cnt)


def cmd_predict(args):
    model_dir = args.model
    with open(os.path.join(model_dir, "config.json")) as f:
        cfg = json.load(f)
    with open(os.path.join(model_dir, "preprocessor.pkl"), "rb") as f:
        pre = pickle.load(f)
    with open(os.path.join(model_dir, "models.pkl"), "rb") as f:
        models = pickle.load(f)

    df = pd.read_csv(os.path.join(args.data, "features.csv"))
    n = len(df)
    n_cls = int(cfg.get("n_cls", 2))
    base_feats = cfg.get("base_features", cfg.get("features", []))
    cat_idx = cfg.get("cat_idx", [])
    classes = cfg.get("classes", list(range(n_cls)))

    X = pre.transform(df)
    arr = build_matrix(X, base_feats, cat_idx)

    n_te = int(cfg.get("n_te", 0))
    if n_te > 0:
        te_path = os.path.join(model_dir, "te.pkl")
        te_arr = None
        if os.path.exists(te_path):
            try:
                with open(te_path, "rb") as f:
                    te = pickle.load(f)
                te_arr = te.transform(df)
            except Exception as e:
                print("[predict] te load failed: %s" % e)
                te_arr = None
        if te_arr is None or te_arr.shape[1] != n_te:
            te_arr = np.zeros((n, n_te), dtype=np.float64)
        arr = np.concatenate([arr, te_arr], axis=1)

    pl = _avg_proba(models.get("lgbs", []), arr, n_cls)
    ph = _avg_proba(models.get("hgbs", []), arr, n_cls)
    w = float(cfg.get("blend_w", 0.5))
    thr = float(cfg.get("threshold", 0.5))

    if pl is None and ph is None:
        proba = np.zeros((n, n_cls), dtype=np.float64)
        proba[:, 0] = 1.0
    elif pl is None:
        proba = ph
    elif ph is None:
        proba = pl
    else:
        proba = w * pl + (1.0 - w) * ph

    if n_cls == 2:
        pred_idx = (proba[:, 1] >= thr).astype(np.int64)
    elif n_cls > 0:
        pred_idx = proba.argmax(axis=1)
    else:
        pred_idx = np.zeros(n, dtype=np.int64)

    out_labels = [classes[int(i)] if int(i) < len(classes) else classes[0] for i in pred_idx]

    out_df = pd.DataFrame({"row_id": np.arange(n, dtype=np.int64), "prediction": out_labels})
    out_dir = os.path.dirname(os.path.abspath(args.output))
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    out_df.to_csv(args.output, index=False)
    print("[predict] wrote %d rows to %s" % (n, args.output))


def main():
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="cmd")

    p_tr = sub.add_parser("train")
    p_tr.add_argument("--data", required=True)
    p_tr.add_argument("--model", required=True)

    p_pr = sub.add_parser("predict")
    p_pr.add_argument("--data", required=True)
    p_pr.add_argument("--model", required=True)
    p_pr.add_argument("--output", required=True)

    args = parser.parse_args()
    if args.cmd == "train":
        cmd_train(args)
    elif args.cmd == "predict":
        cmd_predict(args)
    else:
        parser.print_help()
        raise SystemExit(1)


if __name__ == "__main__":
    main()
